void playMorseCode(const char* morseCode) {
  char* morseCodePtr = morseCode; // pointer to the morse code
  while (*morseCodePtr != '\0') {
    if (*morseCodePtr == '.') { // if the current character is a dot
      tone(8, dotFrequency, dotDuration); // play a tone at the dot frequency for the dot duration
    } else if (*morseCodePtr == '-') { // if the current character is a dash
      tone(8, dotFrequency, dashDuration); // play a tone at the dot frequency for the dash duration
    } else if (*morseCodePtr == ' ') { // if the current character is a space
      delay(spaceDuration); // wait for the space
    }
    morseCodePtr++; // move to the next character in the morse code
  }
  delay(letterSpaceDuration); // wait for the space between letters
}
```

