**Step 1: Create a context**
```jsx
// studentFeedbackContext.js
import { createContext, useState } from 'react';

const StudentFeedbackContext = createContext();

const StudentFeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState({});

  return (
    <StudentFeedbackContext.Provider value={{ feedback, setFeedback }}>
      {children}
    </StudentFeedbackContext.Provider>
  );
};

export { StudentFeedbackProvider };
export default StudentFeedbackContext;
```
**Step 2: Create a form component**
```jsx
// FeedbackForm.js
import { useContext } from 'react';
import { StudentFeedbackContext } from './studentFeedbackContext';

const FeedbackForm = () => {
  const { feedback, setFeedback } = useContext(StudentFeedbackContext);

  const handleInputChange = (event) => {
    setFeedback((prevFeedback) => ({ ...prevFeedback, [event.target.name]: event.target.value }));
  };

  return (
    <form>
      <label>
        Name:
        <input type="text" name="name" value={feedback.name || ''} onChange={handleInputChange} />
      </label>
      <label>
        Course:
        <select name="course" value={feedback.course || ''} onChange={handleInputChange}>
          <option value="">Select a course</option>
          <option value="math">Math</option>
          <option value="english">English</option>
          <option value="science">Science</option>
        </select>
      </label>
      <label>
        Comments:
        <textarea name="comments" value={feedback.comments || ''} onChange={handleInputChange} />
      </label>
      <button type="submit">Submit</button>
    </form>
  );
};

export default FeedbackForm;
```
**Step 3: Create a wrapper component**
```jsx
// FeedbackWrapper.js
import React from 'react';
import { StudentFeedbackProvider } from './studentFeedbackContext';
import FeedbackForm from './FeedbackForm';

const FeedbackWrapper = () => {
  return (
    <StudentFeedbackProvider>
      <FeedbackForm />
    </StudentFeedbackProvider>
  );
};

export default FeedbackWrapper;
```
**Step 4: Use the feedback form component in your App.js file**
```jsx
// App.js
import React from 'react';
import FeedbackWrapper from './FeedbackWrapper';

const App = () => {
  return (
    <div>
      <h1>Student Feedback Form</h1>
      <FeedbackWrapper />
    </div>
  );
};

export default App;
```
