Here's an example AWS Lambda function written in Go that deletes EBS Snapshots based on the `backup_type` tag:
```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-lambda-go/lambda"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("YOUR_REGION")}, nil)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Define a map to store the number of snapshots to keep for each backup type
	keepCounts := map[string]int{
		"monthly":   14,
		"daily":     10,
		"weekly":    4,
		"yearly":    1,
	}

	// Fetch all EBS Snapshots with a tag named "backup_type"
	input := &ec2.DescribeSnapshotsInput{
		TagFilters: []*ec2.TagFilter{
			{
				Key: aws.String("backup_type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	}

	snapshotDesc, err := ec2Svc.DescribeSnapshotsWithContext(ctx, input)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Iterate over the snapshots and delete those that are older than the keep count
	for _, snapshot := range snapshotDesc.Snapshots {
		backupType := *snapshot.Tags[0].Value
		keepCount, ok := keepCounts[backupType]
		if ok {
			// Calculate the number of days since the snapshot was created
			t, err := time.Parse("2006-01-02", *snapshot.StartTime)
			if err != nil {
				log.Println(err)
				continue
			}
			daysSinceCreate := int(time.Since(t / 24 / time.Hour).Hours() / 24)

			// Delete the snapshot if it's older than the keep count
			if backupType == "monthly" && daysSinceCreate > keepCount {
				log.Printf("Deleting monthly snapshot %s (%d days old)\n", *snapshot.SnapshotId, daysSinceCreate)
				ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
			} else if backupType == "daily" && daysSinceCreate > keepCount {
				log.Printf("Deleting daily snapshot %s (%d days old)\n", *snapshot.SnapshotId, daysSinceCreate)
				ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
			} else if backupType == "weekly" && daysSinceCreate > keepCount {
				log.Printf("Deleting weekly snapshot %s (%d days old)\n", *snapshot.SnapshotId, daysSinceCreate)
				ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
			} else if backupType == "yearly" && daysSinceCreate > keepCount {
				log.Printf("Deleting yearly snapshot %s (%d days old)\n", *snapshot.SnapshotId, daysSinceCreate)
				ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
			}
		}
	}

	return nil, nil
}

func main() {
	lambda.Start(handler)
}
```
