#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  if (gpioInitialize() < 0) {
    return 1;
  }

  // Set up GPIO pin 12 as an output
  if (gpioSetup(12, PI_OUTPUT) < 0) {
    return 1;
  }

  // Set the initial state of the pin to LOW (0)
  gpioWrite(12, 0);

  // Main loop
  while (true) {
    // Toggle the pin state
    gpioWrite(12, !gpioRead(12));

    // Wait for 500 milliseconds
    gpioDelay(500 * 1000);
  }

  // Clean up
  gpioTerminate();
  return 0;
}
